-- PREPARE ONLY. Requires both 20261031 catalog migrations.
-- Catalog foundation slice only: do NOT deploy until UI/API/quote/checkin accept
-- arbitrary daily slots end-to-end. No payment/member history is rewritten.
BEGIN;
CREATE FUNCTION package_catalog_daily_slot_valid(slot text) RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT SECURITY INVOKER SET search_path=public,pg_catalog AS $$
 SELECT length(slot)=11 AND slot ~ '^([01][0-9]|2[0-3]):[0-5][0-9]-(([01][0-9]|2[0-3]):[0-5][0-9]|24:00)$'
 AND left(slot,5) < right(slot,5)
$$;
-- Constraint names are those generated by the original catalog migration.
-- Fail closed if the installed schema differs; never drop constraints by pattern.
ALTER TABLE package_catalog DROP CONSTRAINT package_catalog_id_check;
ALTER TABLE package_catalog ADD CONSTRAINT package_catalog_id_check CHECK(id>0);
ALTER TABLE package_catalog DROP CONSTRAINT package_catalog_time_slot_check;
ALTER TABLE package_catalog ADD CONSTRAINT package_catalog_time_slot_check
 CHECK(package_catalog_daily_slot_valid(time_slot));
ALTER TABLE package_catalog_audit DROP CONSTRAINT package_catalog_audit_action_check;
ALTER TABLE package_catalog_audit ADD CONSTRAINT package_catalog_audit_action_check CHECK(action IN ('create','update'));
-- Creation allocates under a table lock below, including any pre-existing IDs.
-- No sequence/backfill is needed; the integer storage limit remains deliberate.
CREATE OR REPLACE FUNCTION package_catalog_action(p_token text,p_action text,p_key uuid,p_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public,pg_catalog AS $$
DECLARE actor members; old package_catalog; current_row package_catalog;
 prior package_catalog_audit; result jsonb; next_id bigint;
BEGIN
 SELECT m.* INTO actor FROM members m WHERE m.id=(SELECT s.member_id FROM auth_sessions s
 WHERE s.token_hash=p_token AND s.mode='NORMAL' AND s.revoked_at IS NULL
 AND s.expires_at>clock_timestamp() LIMIT 1) FOR UPDATE;
 PERFORM 1 FROM auth_sessions WHERE member_id=actor.id AND token_hash=p_token FOR SHARE;
 IF actor.id IS NULL OR actor.role NOT IN ('OWNER','ADMIN') OR actor.role IS NULL
 OR actor.status IS NOT DISTINCT FROM 'SUSPENDED' OR NOT EXISTS(
 SELECT 1 FROM auth_sessions WHERE member_id=actor.id AND token_hash=p_token AND mode='NORMAL'
 AND revoked_at IS NULL AND expires_at>clock_timestamp()) THEN
 RAISE EXCEPTION 'Non-suspended NORMAL OWNER/ADMIN session required' USING ERRCODE='42501'; END IF;
 IF p_action='list' THEN
 SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.id),'[]'::jsonb) INTO result FROM (
 SELECT id,name,label,description,price_satang AS "priceSatang",price_satang::numeric/100 AS price,
 duration_days AS "durationDays",time_slot AS "timeSlot",friend_quota AS "friendCoupons",
 bonus_days AS "bonusDays",version,version AS "catalogVersion",is_active AS "isActive" FROM package_catalog) c;
 RETURN result;
 END IF;
 IF p_action IS NULL OR p_action NOT IN ('create','update') OR p_key IS NULL
 OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN
 RAISE EXCEPTION 'Invalid catalog action' USING ERRCODE='22023'; END IF;
 SELECT * INTO prior FROM package_catalog_audit WHERE actor_id=actor.id AND request_key=p_key;
 IF FOUND THEN
 IF prior.action IS DISTINCT FROM p_action OR prior.payload IS DISTINCT FROM p_payload THEN
 RAISE EXCEPTION 'Request key reused' USING ERRCODE='22023'; END IF;
 RETURN prior.result;
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE k NOT IN
 ('id','expectedVersion','name','label','description','priceSatang','durationDays','timeSlot','friendCoupons','bonusDays','isActive'))
 OR EXISTS(SELECT 1 FROM jsonb_each(p_payload) e WHERE
 (e.key IN ('id','expectedVersion','priceSatang','durationDays','friendCoupons','bonusDays') AND
 (jsonb_typeof(e.value)<>'number' OR e.value::text !~ '^(0|[1-9][0-9]*)$')) OR
 (e.key IN ('name','label','description','timeSlot') AND jsonb_typeof(e.value)<>'string') OR
 (e.key='isActive' AND jsonb_typeof(e.value)<>'boolean')) THEN
 RAISE EXCEPTION 'Invalid catalog payload' USING ERRCODE='22023'; END IF;
 IF p_action='create' THEN
 IF p_payload ?| ARRAY['id','expectedVersion'] OR NOT p_payload ?&
 ARRAY['name','label','description','priceSatang','durationDays','timeSlot','friendCoupons','bonusDays','isActive'] THEN
 RAISE EXCEPTION 'Create requires complete catalog fields without identity/version' USING ERRCODE='22023'; END IF;
 -- Serialize allocation across different actors; lock order is member/session,
 -- then catalog, as with update/order creation. Ordinary inserts also conflict.
 LOCK TABLE package_catalog IN SHARE ROW EXCLUSIVE MODE;
 SELECT coalesce(max(id)::bigint,0)+1 INTO next_id FROM package_catalog;
 IF next_id>2147483647 THEN RAISE EXCEPTION 'Catalog identity exhausted' USING ERRCODE='22003'; END IF;
 INSERT INTO package_catalog(id,name,label,description,price_satang,duration_days,time_slot,friend_quota,bonus_days,is_active)
 VALUES(next_id::integer,btrim(p_payload->>'name'),btrim(p_payload->>'label'),p_payload->>'description',
 (p_payload->>'priceSatang')::integer,(p_payload->>'durationDays')::integer,p_payload->>'timeSlot',
 (p_payload->>'friendCoupons')::integer,(p_payload->>'bonusDays')::integer,(p_payload->>'isActive')::boolean)
 RETURNING * INTO current_row;
 ELSE
 IF coalesce(p_payload->>'id','') !~ '^[1-9][0-9]*$'
 OR coalesce(p_payload->>'expectedVersion','') !~ '^[1-9][0-9]*$' THEN
 RAISE EXCEPTION 'Identity and expectedVersion required' USING ERRCODE='22023'; END IF;
 SELECT * INTO old FROM package_catalog WHERE id=(p_payload->>'id')::integer FOR UPDATE;
 IF old.id IS NULL OR old.version<>(p_payload->>'expectedVersion')::integer THEN
 RAISE EXCEPTION 'Stale catalog version' USING ERRCODE='P0001'; END IF;
 UPDATE package_catalog SET name=coalesce(btrim(p_payload->>'name'),name),label=coalesce(btrim(p_payload->>'label'),label),
 description=coalesce(p_payload->>'description',description),price_satang=coalesce((p_payload->>'priceSatang')::integer,price_satang),
 duration_days=coalesce((p_payload->>'durationDays')::integer,duration_days),time_slot=coalesce(p_payload->>'timeSlot',time_slot),
 friend_quota=coalesce((p_payload->>'friendCoupons')::integer,friend_quota),bonus_days=coalesce((p_payload->>'bonusDays')::integer,bonus_days),
 is_active=coalesce((p_payload->>'isActive')::boolean,is_active),version=version+1
 WHERE id=old.id RETURNING * INTO current_row;
 END IF;
 result:=jsonb_build_object('id',current_row.id,'name',current_row.name,'label',current_row.label,
 'description',current_row.description,'priceSatang',current_row.price_satang,'price',current_row.price_satang::numeric/100,
 'durationDays',current_row.duration_days,'timeSlot',current_row.time_slot,'friendCoupons',current_row.friend_quota,
 'bonusDays',current_row.bonus_days,'version',current_row.version,'catalogVersion',current_row.version,'isActive',current_row.is_active);
 INSERT INTO package_catalog_audit(actor_id,request_key,action,payload,before_snapshot,result)
 VALUES(actor.id,p_key,p_action,p_payload,CASE WHEN p_action='create' THEN '{}'::jsonb ELSE to_jsonb(old) END,result);
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION package_catalog_daily_slot_valid(text),package_catalog_action(text,text,uuid,jsonb) FROM PUBLIC;
COMMIT;
